    RECORD_BARS_REQUEST_BARS_COUNT,
    RECORD_OUTCOMES_REQUEST_OUTCOMES_COUNT,
    RECORD_PRICES_REQUEST_PRICES_COUNT,
    RECORD_QUOTES_REQUEST_QUOTES_COUNT,
